class BloomFilter:
    """
    A Bloom Filter implementation for probabilistic membership testing.

    This design utilizes:
    - A custom bit array represented as an integer for efficient space usage.
    - A Roweis hashing function for generating unique hash indices, ensuring diverse spread.
    - Bit manipulation methods to handle setting and checking bits directly within the integer.
    - Hash function count and bit array size based on expected items and the defined false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.bit_array_size = self._optimal_bit_array_size()
        self.num_hashes = self._optimal_num_hashes()
        self.bit_array = 0  # Using an integer bit array

    def _optimal_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-self.expected_items * math.log(self.false_positive_rate) / (math.log(2) ** 2))

    def _optimal_num_hashes(self) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, round((self.bit_array_size / self.expected_items) * math.log(2)))

    def _row_hash(self, item: str, seed: int) -> int:
        """Generate a hash based on the Roweis algorithm with a seed."""
        return (int(hashlib.sha256((item + str(seed)).encode()).hexdigest(), 16) % self.bit_array_size)

    def _set_bit(self, index: int) -> None:
        """Set a bit at the given index in the integer bit array."""
        self.bit_array |= (1 << index)

    def _check_bit(self, index: int) -> bool:
        """Check if a bit at a given index is set in the integer bit array."""
        return (self.bit_array & (1 << index)) != 0

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for seed in range(self.num_hashes):
            index = self._row_hash(item, seed)
            self._set_bit(index)

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom filter."""
        for seed in range(self.num_hashes):
            index = self._row_hash(item, seed)
            if not self._check_bit(index):
                return False
        return True

import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation using a dynamic-size list to represent the bit array.

    This design incorporates:
    - A custom list to serve as a bit array, expanding as necessary.
    - A simple hash function based on a combination of SHA-256 and modulus for index calculation.
    - The computation of the bit array size and the number of hash functions based on expected items and false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.bit_array_size = self._calculate_bit_array_size()
        self.num_hashes = self._calculate_num_hashes()
        self.bit_array = [0] * self.bit_array_size

    def _calculate_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-self.expected_items * math.log(self.false_positive_rate) / (math.log(2) ** 2))

    def _calculate_num_hashes(self) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, min(30, round((self.bit_array_size / self.expected_items) * math.log(2))))

    def _hash(self, item: str, seed: int) -> int:
        """Hash a string with a given seed using SHA-256."""
        hasher = hashlib.sha256()
        hasher.update((item + str(seed)).encode())
        return int(hasher.hexdigest(), 16) % self.bit_array_size

    def _expand_bit_array(self) -> None:
        """Expand the bit array if exceeding current size."""
        self.bit_array.extend([0] * self.bit_array_size)

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for seed in range(self.num_hashes):
            index = self._hash(item, seed)
            if index >= len(self.bit_array):
                self._expand_bit_array()
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom filter."""
        for seed in range(self.num_hashes):
            index = self._hash(item, seed)
            if index >= len(self.bit_array) or self.bit_array[index] == 0:
                return False
        return True
